package com.clavis.reader;
import android.app.*;
import android.content.*;
import android.os.*;
import android.net.Uri;
import org.json.*;
import org.libtorrent4j.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
public final class TorrentService extends Service {
 static volatile TorrentService live;
 final CopyOnWriteArrayList<TorrentJob> jobs=new CopyOnWriteArrayList<>();
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();
 private LibreTorrentSession session;private boolean stopping;private long saved,checkpointAt;private PowerManager.WakeLock wakeLock;private android.net.ConnectivityManager.NetworkCallback networkCallback;
 static ArrayList<TorrentJob> load(Context c){ArrayList<TorrentJob> out=new ArrayList<>();try{JSONArray data=new JSONArray(c.getSharedPreferences("downloads",0).getString("jobs","[]"));for(int i=0;i<data.length();i++)out.add(new TorrentJob(data.getJSONObject(i)));}catch(Exception ignored){}return out;}
 static List<TorrentJob> current(Context c){TorrentService s=live;return s==null?load(c):new ArrayList<>(s.jobs);}
 static void command(Context c,String action,String value){Intent intent=new Intent(c,TorrentService.class).setAction(action).putExtra("value",value);c.startForegroundService(intent);}
 File folder(TorrentJob job){return new File(new File(getFilesDir(),"TorrentStaging"),job.id);}
 @Override public void onCreate(){super.onCreate();live=this;NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("downloads","Audiobook downloads",NotificationManager.IMPORTANCE_LOW));startForeground(42,notification("Preparing downloads"));
  worker.execute(()->{jobs.addAll(load(this));try{session=new LibreTorrentSession(new File(getNoBackupFilesDir(),"torrent-session"));session.start();for(TorrentJob job:jobs)if(!job.paused&&!job.done)start(job);reconcileQueue();}catch(Exception|LinkageError e){for(TorrentJob job:jobs){job.error="Torrent engine: "+e.getMessage();job.paused=true;}save();}});
  worker.scheduleWithFixedDelay(this::poll,2,2,TimeUnit.SECONDS);
  networkCallback=new android.net.ConnectivityManager.NetworkCallback(){@Override public void onAvailable(android.net.Network network){if(!worker.isShutdown())worker.execute(()->{if(session!=null&&session.isRunning())session.reopenNetworkSockets();});}};getSystemService(android.net.ConnectivityManager.class).registerDefaultNetworkCallback(networkCallback);
 }
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null){String action=intent.getAction(),value=intent.getStringExtra("value");worker.execute(()->{try{
   if("publishall".equals(action)){for(TorrentJob job:jobs)if(job.done&&folder(job).isDirectory()){job.imported=false;importBook(job);}}else if("add".equals(action)){MagnetLink link=MagnetLink.parse(value);TorrentJob found=null;for(TorrentJob j:jobs)if(j.id.equals(link.id))found=j;if(found==null){found=new TorrentJob(link);jobs.add(found);}if(!found.done){found.paused=false;found.error="";start(found);}}
   else for(TorrentJob job:jobs)if(job.id.equals(value)){TorrentHandle h=handle(job);if("pause".equals(action)){if(session!=null)session.checkpoint(false);job.paused=true;job.state="Paused";job.rate=0;job.etaSeconds=job.estimate.remainingSeconds(SystemClock.elapsedRealtime(),job.bytes,job.total,false);if(h!=null){h.unsetFlags(TorrentFlags.AUTO_MANAGED);h.pause();}}else if("resume".equals(action)){job.paused=false;job.error="";start(job);}else if("reannounce".equals(action)){if(h!=null){h.forceReannounce();h.forceDHTAnnounce();h.forceLSDAnnounce();}}else if("publish".equals(action)){importBook(job);}else if("remove".equals(action)){if(h!=null)session.remove(h);jobs.remove(job);}break;}
  }catch(Exception|LinkageError e){for(TorrentJob job:jobs)if(job.id.equals(value)||job.magnet.equals(value)){job.error=e.getMessage();job.paused=true;} }reconcileQueue();save();});}return START_STICKY;}
 private TorrentHandle handle(TorrentJob job){if(session==null||!session.isRunning())return null;TorrentHandle h=session.find(AddTorrentParams.parseMagnetUri(job.magnet).getInfoHashes().getBest());return h!=null&&h.isValid()?h:null;}
 private void start(TorrentJob job){if(session==null||!session.isRunning())throw new IllegalStateException("Torrent engine unavailable");File dir=folder(job);if(!dir.isDirectory()&&!dir.mkdirs())throw new IllegalStateException("Cannot create download folder");TorrentHandle h=handle(job);if(h==null){session.add(job.magnet,dir);job.state="Finding peers and metadata";}else{h.unsetFlags(TorrentFlags.AUTO_MANAGED);h.resume();job.state="Resuming";}}
 private void reconcileQueue(){int slots=DownloadSettings.parallel(this),running=0;for(TorrentJob job:jobs){if(job.paused||job.done){job.queued=false;continue;}boolean queue=running++>=slots;TorrentHandle h=handle(job);if(queue){job.rate=0;job.etaSeconds=job.estimate.remainingSeconds(SystemClock.elapsedRealtime(),job.bytes,job.total,false);job.state="Queued - waiting for a download slot";if(h!=null){h.unsetFlags(TorrentFlags.AUTO_MANAGED);h.pause();}}else if(job.queued&&h!=null){h.resume();job.state="Resuming";}job.queued=queue;}}
 private void poll(){if(stopping)return;try{reconcileQueue();boolean active=false;int count=0;long rate=0;for(TorrentJob job:jobs){if(job.paused||job.done||job.queued)continue;active=true;count++;TorrentHandle h=handle(job);if(h==null)continue;TorrentStatus s=h.status(true);if(!s.name().isEmpty()&&!s.name().equals(job.id))job.name=s.name();job.progress=s.progress();job.bytes=s.totalWantedDone();job.total=s.totalWanted();job.rate=s.downloadPayloadRate();job.etaSeconds=job.estimate.remainingSeconds(SystemClock.elapsedRealtime(),job.bytes,job.total,true);job.peers=s.numPeers();job.seeds=s.numSeeds();job.knownSeeds=s.listSeeds();job.dhtNodes=session.dhtNodes();rate+=job.rate;job.state=job.total==0?"Finding peers and metadata":job.seeds==0&&job.rate==0?"Waiting for a peer with available pieces":s.state().toString().replace('_',' ');if(s.errorCode().getValue()!=0){job.error=s.errorCode().getMessage();job.paused=true;h.unsetFlags(TorrentFlags.AUTO_MANAGED);h.pause();}if(s.isFinished()){h.unsetFlags(TorrentFlags.AUTO_MANAGED);h.pause();job.done=true;job.etaSeconds=0;job.rate=0;job.progress=1;job.state="Completed";importBook(job);save();}}
  if(SystemClock.elapsedRealtime()-checkpointAt>30000){session.checkpoint(false);checkpointAt=SystemClock.elapsedRealtime();}
  if(SystemClock.elapsedRealtime()-saved>5000){save();saved=SystemClock.elapsedRealtime();}
  if(!active){save();stopping=true;stopSelf();}else{keepAwake();getSystemService(NotificationManager.class).notify(42,notification(count+" download(s) - "+android.text.format.Formatter.formatShortFileSize(this,rate)+"/s"));}
 }catch(Exception|LinkageError e){for(TorrentJob job:jobs)if(!job.done&&!job.paused){job.error=e.getMessage();job.paused=true;}save();}}
 private void importBook(TorrentJob job){if(job.imported)return;try{job.state="Saving to Clavis";ArrayList<Book> imported=SharedDownloads.publishTorrent(this,folder(job),job.name);ArrayList<Book> library=Store.load(this);String staging=Uri.fromFile(folder(job)).toString();ArrayList<Book> previous=new ArrayList<>();for(Book old:library)if(old.uri.equals(staging)||old.uri.startsWith(staging+"/"))previous.add(old);for(Book book:imported){if(book.title.equals(job.id))book.title=job.name.replaceFirst("(?i)\\.(mp3|m4a|m4b|aac|flac|ogg|opus|wav|wma)$", "");for(Book old:previous)if(old.title.equals(book.title)||(previous.size()==1&&imported.size()==1)){book.position=old.position;book.duration=old.duration;book.speed=old.speed;book.saved=old.saved;book.chapterIndex=Math.min(old.chapterIndex,book.chapterCount()-1);String marks=getSharedPreferences("bookmarks",0).getString("bookmarks:"+old.uri,"[]");getSharedPreferences("bookmarks",0).edit().putString("bookmarks:"+book.uri,marks).apply();if(getSharedPreferences("navigation",0).getString("lastAudioUri","").equals(old.uri))getSharedPreferences("navigation",0).edit().putString("lastAudioUri",book.uri).apply();break;}if(library.stream().noneMatch(item->item.uri.equals(book.uri)))library.add(book);}if(!imported.isEmpty())library.removeAll(previous);Store.save(this,library);job.imported=true;if(!imported.isEmpty()){TorrentHandle finished=handle(job);if(finished!=null)session.remove(finished);PlaybackService playing=PlaybackService.live;if(playing==null||!playing.uri.startsWith(staging))SharedDownloads.clearTemporary(folder(job));}if(imported.isEmpty())job.error="Download complete; no supported audio files found";}catch(Exception e){job.error="Download complete; import failed: "+e.getMessage();}}
 private void save(){JSONArray data=new JSONArray();for(TorrentJob job:jobs)data.put(job.json());getSharedPreferences("downloads",0).edit().putString("jobs",data.toString()).apply();}
 private Notification notification(String text){PendingIntent open=PendingIntent.getActivity(this,42,new Intent(this,DownloadsActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new Notification.Builder(this,"downloads").setSmallIcon(R.drawable.ic_listen_audio).setContentTitle("Clavis downloads").setContentText(text).setContentIntent(open).setOngoing(true).build();}
 @Override public void onTimeout(int startId,int type){worker.execute(()->{for(TorrentJob job:jobs)if(!job.done)job.paused=true;save();stopSelf();});}
 @Override public void onDestroy(){live=null;if(networkCallback!=null)getSystemService(android.net.ConnectivityManager.class).unregisterNetworkCallback(networkCallback);if(wakeLock!=null&&wakeLock.isHeld())wakeLock.release();worker.execute(()->{save();if(session!=null){session.checkpoint(true);session.stop();}});worker.shutdown();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 // CPU wake-lock lifecycle adapted from LibreTorrent (GPL-3.0-or-later); bounded and renewed only during active transfers.
 private void keepAwake(){if(wakeLock==null){wakeLock=getSystemService(PowerManager.class).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"Clavis:TorrentTransfer");wakeLock.setReferenceCounted(false);}wakeLock.acquire(10*60*1000L);}
 @Override public IBinder onBind(Intent intent){return null;}
}
